PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
    "id"                    TEXT PRIMARY KEY NOT NULL,
    "checksum"              TEXT NOT NULL,
    "finished_at"           DATETIME,
    "migration_name"        TEXT NOT NULL,
    "logs"                  TEXT,
    "rolled_back_at"        DATETIME,
    "started_at"            DATETIME NOT NULL DEFAULT current_timestamp,
    "applied_steps_count"   INTEGER UNSIGNED NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS "Challenge" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "slug" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "answerType" TEXT NOT NULL,
    "correctAnswer" TEXT,
    "choices" TEXT,
    "xpValue" INTEGER NOT NULL,
    "rewardMode" TEXT NOT NULL DEFAULT 'XP',
    "questionImage" BLOB,
    "questionImageMimeType" TEXT,
    "unlockAudio" BLOB,
    "unlockAudioMimeType" TEXT,
    "unlockText" TEXT,
    "unlockLinkUrl" TEXT,
    "unlockLinkLabel" TEXT,
    "unlockImage" BLOB,
    "unlockImageMimeType" TEXT,
    "unlockVideo" BLOB,
    "unlockVideoMimeType" TEXT,
    "rewardBackgroundEffect" TEXT,
    "rewardBorderStyle" TEXT,
    "rewardIcon" TEXT,
    "rewardRibbonText" TEXT,
    "rewardNameSuffix" TEXT,
    "rewardOutlineColorPicker" BOOLEAN NOT NULL DEFAULT false,
    "rewardBackgroundColorPicker" BOOLEAN NOT NULL DEFAULT false,
    "rewardPrize" TEXT,
    "minClearance" TEXT NOT NULL DEFAULT 'UNCLASSIFIED',
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "opensAt" DATETIME,
    "closesAt" DATETIME,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
, "maxAttempts" INTEGER, "dropAnnouncedAt" DATETIME, "webhookUrl" TEXT);
CREATE TABLE IF NOT EXISTS "AdminAudit" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "action" TEXT NOT NULL,
    "detail" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "AppSetting" (
    "key" TEXT NOT NULL PRIMARY KEY,
    "value" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "Submission" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "employeeId" TEXT NOT NULL,
    "challengeId" TEXT NOT NULL,
    "answerRaw" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "xpAwarded" INTEGER NOT NULL DEFAULT 0,
    "attempts" INTEGER NOT NULL DEFAULT 1,
    "submittedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "reviewedBy" TEXT,
    "reviewedAt" DATETIME,
    CONSTRAINT "Submission_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "Submission_challengeId_fkey" FOREIGN KEY ("challengeId") REFERENCES "Challenge" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ChatMessage" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "employeeId" TEXT NOT NULL,
    "body" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ChatMessage_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ChatReaction" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "messageId" TEXT NOT NULL,
    "employeeId" TEXT NOT NULL,
    "emoji" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ChatReaction_messageId_fkey" FOREIGN KEY ("messageId") REFERENCES "ChatMessage" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "ChatReaction_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Employee" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "email" TEXT NOT NULL,
    "displayName" TEXT NOT NULL,
    "pinHash" TEXT,
    "rogueOverride" BOOLEAN NOT NULL DEFAULT false,
    "isAdmin" BOOLEAN NOT NULL DEFAULT false,
    "isHidden" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "photo" BLOB,
    "photoMimeType" TEXT,
    "photoUpdatedAt" DATETIME,
    "lastChatReadAt" DATETIME,
    "chatActiveAt" DATETIME,
    "typingAt" DATETIME,
    "isSystemAccount" BOOLEAN NOT NULL DEFAULT false
, "extraPasswordHash" TEXT);
CREATE TABLE IF NOT EXISTS "BadgeFlare" (
    "employeeId" TEXT NOT NULL PRIMARY KEY,
    "achievements" TEXT NOT NULL DEFAULT '[]',
    "outlineColor" TEXT,
    "backgroundColor" TEXT,
    "backgroundEffect" TEXT,
    "codenameOverride" TEXT,
    "motto" TEXT,
    "iconOverride" TEXT,
    "borderStyle" TEXT,
    "ribbonText" TEXT,
    "nameSuffix" TEXT,
    "secretBackText" TEXT,
    "holoSheen" BOOLEAN NOT NULL DEFAULT false,
    "psaGrade" BOOLEAN NOT NULL DEFAULT false,
    "expiresAt" DATETIME,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "BadgeFlare_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "Challenge_slug_key" ON "Challenge"("slug");
CREATE INDEX "Submission_employeeId_idx" ON "Submission"("employeeId");
CREATE INDEX "Submission_challengeId_idx" ON "Submission"("challengeId");
CREATE UNIQUE INDEX "Submission_employeeId_challengeId_key" ON "Submission"("employeeId", "challengeId");
CREATE INDEX "ChatMessage_createdAt_idx" ON "ChatMessage"("createdAt");
CREATE INDEX "ChatReaction_messageId_idx" ON "ChatReaction"("messageId");
CREATE UNIQUE INDEX "ChatReaction_messageId_employeeId_emoji_key" ON "ChatReaction"("messageId", "employeeId", "emoji");
CREATE UNIQUE INDEX "Employee_email_key" ON "Employee"("email");
COMMIT;
