INSERT INTO Challenge VALUES('cmu61xowk000fsjkmm78gaa46','security-connections-1','SECURITY CONNECTIONS #1',replace(replace('16 words. 4 groups. Think you can make the connections?\r\n\r\nPick four words you think belong together and submit your guess. Get it right and the group locks in, revealing the connection. Get it wrong and you''ll burn an attempt, but your picks stay put so you can swap one out and try again.\r\n\r\nFind all four connections before your attempts run out to clear the mission and earn your XP.\r\n\r\nChoose wisely. Some words may not be as obvious as they seem.','\r',char(13)),'\n',char(10)),'CONNECTIONS','[{"label":"Ways You Prove It''s You","words":["PASSKEY","FACE ID","YUBIKEY","OKTA"]},{"label":"Tools You Use At Dutchie","words":["SLACK","ZOOM","GMAIL","GONG"]},{"label":"Phishing''s Evil Cousins","words":["PHISHING","VISHING","SMISHING","QUISHING"]},{"label":"Malware''s Rogues Gallery","words":["RANSOMWARE","SPYWARE","ADWARE","TROJAN"]}]','["ADWARE","GMAIL","ZOOM","SMISHING","RANSOMWARE","SPYWARE","QUISHING","SLACK","PASSKEY","TROJAN","VISHING","YUBIKEY","PHISHING","GONG","FACE ID","OKTA"]',30,'XP',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'crt','pulse','trophy',NULL,NULL,0,0,NULL,'UNCLASSIFIED',1,NULL,NULL,1789681128789,1789686025124,5,1789681128797,'https://dutchie.tines.com/webhook/security-slack-alerts-2/d6da7026bf6f38b56d9dee59e9d32778');
INSERT INTO Challenge VALUES('cmu63n20z0000zd0m1ln96dor','security-connections-2','SECURITY CONNECTIONS #2',replace(replace('Sixteen words. Four hidden connections.\r\n\r\nYour job is to figure out which four words belong together. Pick your four and submit your guess. Nail it, and the group locks in and reveals what connects them. Miss it, and you lose an attempt, but your picks stay put so you can swap a word and try again.\r\n\r\nFind all four groups before you run out of guesses to clear the mission.\r\n\r\nSeems easy enough...right?','\r',char(13)),'\n',char(10)),'CONNECTIONS','[{"label":"Things Dutchies Should Verify","words":["SENDER","DOMAIN","URL","IDENTITY"]},{"label":"Ways Dutchies Authenticate","words":["PASSWORD","PASSKEY","FACE ID","SECURITY KEY"]},{"label":"Social Engineering Tactics","words":["URGENCY","SECRECY","PRESSURE","AUTHORITY"]},{"label":"Things Dutchies Protect","words":["ACCESS","DATA","DEVICES","PRIVACY"]}]','["AUTHORITY","PRIVACY","SECRECY","IDENTITY","DOMAIN","DATA","SENDER","ACCESS","PASSWORD","PRESSURE","URL","FACE ID","DEVICES","SECURITY KEY","PASSKEY","URGENCY"]',40,'XP',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,'UNCLASSIFIED',1,NULL,NULL,1789683991811,1789685769276,5,1789684406533,'https://dutchie.tines.com/webhook/security-slack-alerts-2/d6da7026bf6f38b56d9dee59e9d32778');
INSERT INTO Challenge VALUES('cmu63n2190001zd0m2dp0gk2u','security-connections-3','SECURITY CONNECTIONS #3',replace(replace('----PROCESS 420----\r\nconnections.\r\ncute.\r\nsecurity gives you sixteen words and suddenly you''re all threat analysts.\r\nfine.\r\nlet''s play.\r\ni picked the categories this time.\r\ndon''t worry.\r\nthey''re all about you.\r\nfive mistakes and you''re done.\r\ntry not to disappoint me.\r\ni''ve already seen enough of that.','\r',char(13)),'\n',char(10)),'CONNECTIONS','[{"label":"THINGS YOU BLINDLY TRUST","words":["SLACK","EMAIL","OKTA","ZOOM"]},{"label":"THINGS YOU GIVE AWAY","words":["ACCESS","DATA","APPROVAL","PERMISSION"]},{"label":"SECURITY''S LITTLE GAME","words":["XP","BADGES","CLEARANCE","CHALLENGES"]},{"label":"MY FAVORITE VULNERABILITY","words":["PEOPLE","CURIOSITY","TRUST","EGO"]}]','["PERMISSION","APPROVAL","PEOPLE","OKTA","CHALLENGES","ZOOM","DATA","XP","CLEARANCE","CURIOSITY","TRUST","EMAIL","EGO","ACCESS","SLACK","BADGES"]',60,'XP',NULL,NULL,NULL,NULL,replace(replace('there.\r\nthat wasn''t so hard.\r\nyou trust what looks familiar.\r\nyou give away what you''re asked for.\r\nyou chase points because security put them on a leaderboard.\r\nand all i had to do...\r\nwas give you something to click.\r\nkeep playing, dutchie.\r\nyou''re doing wonderfully.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,'SECRET',1,NULL,NULL,1789683991821,1789686672974,5,1789684393680,'https://dutchie.tines.com/webhook/security-slack-alerts-2/d6da7026bf6f38b56d9dee59e9d32778');
